    float turn = float(packed >> 13) / 2048;
    uint textureFlags = uint(material.normalMatrix[0][1]);
    if (strength > 0 && (textureFlags & (1u << 20)))
    {
        float2 uv = textureFlags & (1u << 21) ? uv1 : uv0;
        uint width, height;
